export const conhecimentosBancariosQuestions: Question[] = [
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-01", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Órgãos normativos", "difficulty": "iniciante", "type": "multiple-choice", "statement": "No Sistema Financeiro Nacional, o órgão responsável por formular a política da moeda e do crédito e por expedir as normas gerais que regem as instituições financeiras é o", "alternatives": [{"id": "A", "text": "Conselho Monetário Nacional (CMN)"}, {"id": "B", "text": "Banco Central do Brasil (BCB)"}, {"id": "C", "text": "Comissão de Valores Mobiliários (CVM)"}, {"id": "D", "text": "Conselho de Controle de Atividades Financeiras (Coaf)"}, {"id": "E", "text": "Superintendência de Seguros Privados (Susep)"}], "correctAnswer": "A", "explanation": "O CMN é o órgão normativo do SFN, criado pela Lei 4.595/1964. Ele estabelece as diretrizes da política monetária, creditícia e cambial; o Banco Central executa essas diretrizes e fiscaliza as instituições.", "alternativeExplanations": {"A": "Correto. O CMN é o órgão normativo máximo do SFN: define diretrizes da política monetária e creditícia e edita as normas que as instituições devem seguir.", "B": "O BCB executa e fiscaliza as normas do CMN; é órgão supervisor e executor, não o normativo máximo.", "C": "A CVM regula e fiscaliza o mercado de valores mobiliários, não a política da moeda e do crédito.", "D": "O Coaf é a unidade de inteligência financeira voltada à prevenção da lavagem de dinheiro.", "E": "A Susep supervisiona seguros, capitalização e previdência aberta."}, "tags": ["sfn", "cmn", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["sfn", "cmn"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-02", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Supervisão de mercados", "difficulty": "iniciante", "type": "multiple-choice", "statement": "A fiscalização das operações de seguros, de títulos de capitalização e dos planos de previdência complementar aberta cabe à", "alternatives": [{"id": "A", "text": "Superintendência Nacional de Previdência Complementar (Previc)"}, {"id": "B", "text": "Superintendência de Seguros Privados (Susep)"}, {"id": "C", "text": "Comissão de Valores Mobiliários (CVM)"}, {"id": "D", "text": "Secretaria do Tesouro Nacional"}, {"id": "E", "text": "Caixa Econômica Federal"}], "correctAnswer": "B", "explanation": "No SFN, o mercado de seguros privados tem o CNSP como órgão normativo e a Susep como supervisora. Ela fiscaliza seguradoras, sociedades de capitalização e entidades abertas de previdência complementar.", "alternativeExplanations": {"A": "A Previc fiscaliza a previdência complementar fechada (fundos de pensão), não a aberta.", "B": "Correto. A Susep é a autarquia supervisora do mercado de seguros, capitalização e previdência aberta.", "C": "A CVM cuida do mercado de valores mobiliários, como ações e debêntures.", "D": "O Tesouro administra a dívida pública e as contas da União; não supervisiona seguros.", "E": "A Caixa é instituição financeira operadora, não órgão supervisor."}, "tags": ["sfn", "susep", "seguros", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["sfn", "susep", "seguros"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-03", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Produtos e serviços bancários", "subtopic": "Caderneta de poupança", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Em relação à caderneta de poupança mantida por pessoa física, é correto afirmar que", "alternatives": [{"id": "A", "text": "os rendimentos são creditados diariamente, independentemente da data de aniversário"}, {"id": "B", "text": "os rendimentos sofrem retenção de 15% de Imposto de Renda no resgate"}, {"id": "C", "text": "os rendimentos são isentos de Imposto de Renda e o saldo é coberto pelo FGC dentro dos limites do fundo"}, {"id": "D", "text": "os valores aplicados não contam com nenhuma garantia de crédito"}, {"id": "E", "text": "a remuneração é sempre igual a 100% da taxa Selic"}], "correctAnswer": "C", "explanation": "A caderneta de poupança tem rendimento mensal na data de aniversário, isenção de IR para pessoas físicas e cobertura do FGC. Sua remuneração é de 0,5% ao mês + TR quando a Selic supera 8,5% ao ano, ou 70% da Selic + TR nos demais casos.", "alternativeExplanations": {"A": "Na poupança, o rendimento é creditado mensalmente, na data de aniversário do depósito.", "B": "Para pessoa física, os rendimentos da poupança são isentos de IR.", "C": "Correto. A poupança de pessoa física não paga IR sobre os rendimentos e conta com a garantia do FGC.", "D": "A poupança está entre os depósitos cobertos pelo FGC.", "E": "A remuneração segue regra própria: 0,5% ao mês + TR, ou 70% da Selic + TR quando a Selic estiver em até 8,5% ao ano."}, "tags": ["poupanca", "produtos-bancarios", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["poupanca", "produtos-bancarios"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-04", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Fundo Garantidor de Créditos", "subtopic": "Cobertura", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Entre os investimentos a seguir, aquele que conta com a garantia do Fundo Garantidor de Créditos (FGC) é o", "alternatives": [{"id": "A", "text": "fundo de investimento em ações"}, {"id": "B", "text": "plano de previdência VGBL"}, {"id": "C", "text": "debênture de empresa de capital aberto"}, {"id": "D", "text": "Certificado de Depósito Bancário (CDB)"}, {"id": "E", "text": "ação negociada na B3"}], "correctAnswer": "D", "explanation": "O FGC protege depósitos e alguns títulos bancários, como conta corrente, poupança, CDB, RDB, LCI, LCA e letras de câmbio. Fundos de investimento, previdência, ações e debêntures não têm essa cobertura.", "alternativeExplanations": {"A": "Cotas de fundos de investimento não têm cobertura do FGC.", "B": "Planos de previdência não são cobertos pelo FGC; seguem regras próprias de proteção.", "C": "Debêntures são dívidas de empresas, não depósitos bancários, e não contam com o FGC.", "D": "Correto. O CDB é um depósito a prazo e está entre os produtos cobertos pelo FGC.", "E": "Ações são títulos de renda variável e não têm garantia do FGC."}, "tags": ["fgc", "investimentos", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["fgc", "investimentos"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-05", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Pix", "subtopic": "Chaves Pix", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Para receber um Pix, o usuário pode cadastrar uma chave vinculada à sua conta. NÃO é um tipo de chave Pix aceito pelo arranjo:", "alternatives": [{"id": "A", "text": "CPF do titular da conta"}, {"id": "B", "text": "endereço de e-mail"}, {"id": "C", "text": "número de telefone celular"}, {"id": "D", "text": "chave aleatória gerada pela instituição"}, {"id": "E", "text": "número do cartão de débito"}], "correctAnswer": "E", "explanation": "As chaves Pix podem ser CPF ou CNPJ, e-mail, número de celular ou chave aleatória. A chave é um apelido que identifica a conta de destino, sem que o pagador precise saber agência e número da conta.", "alternativeExplanations": {"A": "O CPF (ou CNPJ, para empresas) é um dos tipos de chave Pix.", "B": "O e-mail é um tipo de chave Pix aceito.", "C": "O celular é um dos tipos de chave Pix.", "D": "A chave aleatória (EVP) é um tipo de chave Pix aceito.", "E": "Correto. O número do cartão não é chave Pix; as chaves são CPF/CNPJ, e-mail, celular e chave aleatória."}, "tags": ["pix", "meios-de-pagamento", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pix", "meios-de-pagamento"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-06", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Garantias", "subtopic": "Garantias pessoais", "difficulty": "iniciante", "type": "multiple-choice", "statement": "A garantia pessoal prestada em títulos de crédito, como nota promissória e duplicata, por meio da qual um terceiro se obriga ao pagamento do título, é denominada", "alternatives": [{"id": "A", "text": "aval"}, {"id": "B", "text": "fiança"}, {"id": "C", "text": "hipoteca"}, {"id": "D", "text": "penhor"}, {"id": "E", "text": "alienação fiduciária"}], "correctAnswer": "A", "explanation": "As garantias pessoais (fidejussórias) são o aval e a fiança. O aval é próprio dos títulos de crédito e lançado no título; a fiança é acessória a um contrato. Hipoteca, penhor e alienação fiduciária são garantias reais.", "alternativeExplanations": {"A": "Correto. O aval é a garantia cambial dada em títulos de crédito, lançada no próprio título.", "B": "A fiança é garantia pessoal contratual, ligada a um contrato, e não ao título de crédito.", "C": "A hipoteca é garantia real sobre imóveis, não garantia pessoal.", "D": "O penhor é garantia real sobre bens móveis.", "E": "A alienação fiduciária é garantia real em que a propriedade do bem é transferida ao credor até a quitação."}, "tags": ["garantias", "aval", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["garantias", "aval"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-i-07", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Prevenção à lavagem de dinheiro", "subtopic": "Etapas da lavagem", "difficulty": "iniciante", "type": "multiple-choice", "statement": "Na etapa inicial da lavagem de dinheiro, o criminoso busca introduzir os recursos ilícitos no sistema econômico, por exemplo com depósitos fracionados em contas bancárias. Essa etapa é chamada de", "alternatives": [{"id": "A", "text": "ocultação"}, {"id": "B", "text": "colocação"}, {"id": "C", "text": "integração"}, {"id": "D", "text": "compensação"}, {"id": "E", "text": "liquidação"}], "correctAnswer": "B", "explanation": "A lavagem de dinheiro costuma ser descrita em três etapas: colocação (entrada dos recursos no sistema), ocultação ou estratificação (movimentações para apagar a origem) e integração (retorno à economia com aparência legal).", "alternativeExplanations": {"A": "A ocultação (ou estratificação) vem depois e consiste em dificultar o rastreamento, com muitas movimentações.", "B": "Correto. A colocação é a introdução do dinheiro ilícito no sistema financeiro.", "C": "A integração é a etapa final, em que os recursos voltam à economia com aparência lícita.", "D": "Compensação é processo de liquidação de pagamentos, não etapa da lavagem.", "E": "Liquidação é a conclusão financeira de uma operação, não etapa da lavagem."}, "tags": ["pld", "lavagem-de-dinheiro", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pld", "lavagem-de-dinheiro"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-01", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Política monetária", "subtopic": "Copom e Selic", "difficulty": "medio", "type": "multiple-choice", "statement": "O Comitê de Política Monetária (Copom) do Banco Central tem como principal atribuição", "alternatives": [{"id": "A", "text": "definir a meta de inflação que o Banco Central deve perseguir"}, {"id": "B", "text": "fixar o limite de garantia do FGC"}, {"id": "C", "text": "definir a meta da taxa Selic, buscando o cumprimento da meta de inflação"}, {"id": "D", "text": "autorizar o funcionamento de novas instituições financeiras"}, {"id": "E", "text": "definir as alíquotas do Imposto sobre Operações Financeiras (IOF)"}], "correctAnswer": "C", "explanation": "O Copom, órgão do Banco Central, reúne-se periodicamente para definir a meta da taxa Selic. A meta de inflação é fixada pelo CMN, e cabe ao Banco Central, por meio da política de juros, buscar o seu cumprimento.", "alternativeExplanations": {"A": "A meta de inflação é definida pelo CMN; o Copom persegue essa meta.", "B": "O limite do FGC é definido em seu estatuto, aprovado pelo CMN, e não pelo Copom.", "C": "Correto. O Copom define a meta da Selic, principal instrumento para levar a inflação à meta.", "D": "Autorizações de funcionamento são atribuição do Banco Central, fora do Copom.", "E": "O IOF é tributo federal, com alíquotas definidas pelo Poder Executivo."}, "tags": ["copom", "selic", "politica-monetaria", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["copom", "selic", "politica-monetaria"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-02", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Política monetária", "subtopic": "Instrumentos", "difficulty": "medio", "type": "multiple-choice", "statement": "Se o Banco Central eleva a alíquota do recolhimento compulsório sobre os depósitos à vista, o efeito esperado é", "alternatives": [{"id": "A", "text": "o aumento da oferta de crédito, pois os bancos passam a ter mais reservas livres"}, {"id": "B", "text": "a queda imediata da meta da taxa Selic"}, {"id": "C", "text": "a ampliação do limite de cobertura do FGC"}, {"id": "D", "text": "a redução dos recursos disponíveis para os bancos emprestarem, contraindo a liquidez da economia"}, {"id": "E", "text": "a emissão de mais moeda pelo Tesouro Nacional"}], "correctAnswer": "D", "explanation": "O recolhimento compulsório obriga os bancos a manter no Banco Central uma parte dos depósitos. Quando a alíquota sobe, sobra menos dinheiro para emprestar: é uma medida contracionista. Ao lado do open market e do redesconto, é um dos instrumentos clássicos de política monetária.", "alternativeExplanations": {"A": "Ocorre o contrário: reservas recolhidas ao BC deixam de estar livres para empréstimos.", "B": "A meta da Selic é definida pelo Copom; o compulsório é outro instrumento.", "C": "O compulsório não tem relação com o limite de garantia do FGC.", "D": "Correto. Mais compulsório significa mais dinheiro retido no BC e menos recursos para empréstimos.", "E": "A emissão de moeda é feita pelo BC, e o aumento do compulsório tem efeito contracionista."}, "tags": ["compulsorio", "politica-monetaria", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["compulsorio", "politica-monetaria"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-03", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Fundo Garantidor de Créditos", "subtopic": "Limites de cobertura", "difficulty": "medio", "type": "multiple-choice", "statement": "Um investidor pessoa física tem R$ 300 mil em CDB de um único banco, que sofreu liquidação extrajudicial. Considerando as regras atuais do FGC, ele tem direito a receber do fundo até", "alternatives": [{"id": "A", "text": "R$ 300 mil, pois o CDB é integralmente garantido"}, {"id": "B", "text": "R$ 100 mil"}, {"id": "C", "text": "R$ 1 milhão"}, {"id": "D", "text": "nada, pois CDB não é coberto pelo FGC"}, {"id": "E", "text": "R$ 250 mil"}], "correctAnswer": "E", "explanation": "O FGC garante até R$ 250 mil por CPF ou CNPJ em cada instituição ou conglomerado, com teto global de R$ 1 milhão a cada quatro anos para garantias pagas a uma mesma pessoa. Os R$ 50 mil que excedem o limite entram no processo de liquidação do banco.", "alternativeExplanations": {"A": "A cobertura tem teto por CPF e por instituição: R$ 250 mil.", "B": "Esse valor não corresponde ao limite atual, que é de R$ 250 mil.", "C": "R$ 1 milhão é o teto global por CPF a cada quatro anos, somando todas as instituições, e não o limite por instituição.", "D": "O CDB está entre os produtos cobertos pelo FGC.", "E": "Correto. A garantia é de até R$ 250 mil por CPF por instituição ou conglomerado."}, "tags": ["fgc", "cdb", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["fgc", "cdb"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-04", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Garantias", "subtopic": "Alienação fiduciária", "difficulty": "medio", "type": "multiple-choice", "statement": "Na alienação fiduciária em garantia de um financiamento de veículo, até a quitação da dívida,", "alternatives": [{"id": "A", "text": "o credor detém a propriedade resolúvel e a posse indireta, e o devedor fica com a posse direta do bem"}, {"id": "B", "text": "o devedor tem a propriedade plena e o credor apenas um direito de preferência"}, {"id": "C", "text": "o bem fica na posse do credor até o pagamento da última parcela"}, {"id": "D", "text": "a garantia é pessoal, prestada por um terceiro que assina o contrato"}, {"id": "E", "text": "o credor só pode retomar o bem após o pagamento de metade das parcelas"}], "correctAnswer": "A", "explanation": "Na alienação fiduciária, o devedor transfere ao credor a propriedade resolúvel do bem, que volta ao devedor quando a dívida é paga. O devedor continua usando o bem (posse direta). É muito usada em financiamentos de veículos e imóveis.", "alternativeExplanations": {"A": "Correto. O devedor usa o bem, mas a propriedade fica com o credor até o pagamento.", "B": "Na alienação fiduciária a propriedade passa ao credor, de forma resolúvel.", "C": "O devedor mantém a posse direta e pode usar o veículo.", "D": "A alienação fiduciária é garantia real, sobre o próprio bem.", "E": "Não existe essa regra; o inadimplemento autoriza o credor a buscar a retomada."}, "tags": ["garantias", "alienacao-fiduciaria", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["garantias", "alienacao-fiduciaria"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-05", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Produtos e serviços bancários", "subtopic": "Previdência complementar", "difficulty": "medio", "type": "multiple-choice", "statement": "Um cliente faz a declaração completa do Imposto de Renda e contribui para o INSS. Para ele, a vantagem tributária característica do PGBL em relação ao VGBL é", "alternatives": [{"id": "A", "text": "a isenção total de Imposto de Renda no resgate"}, {"id": "B", "text": "poder deduzir as contribuições da base de cálculo do IR, até 12% da renda bruta tributável anual"}, {"id": "C", "text": "a incidência de IR somente sobre os rendimentos no resgate"}, {"id": "D", "text": "a garantia do FGC sobre o saldo acumulado"}, {"id": "E", "text": "a possibilidade de deduzir 100% das contribuições, sem limite"}], "correctAnswer": "B", "explanation": "O PGBL é indicado para quem faz a declaração completa: as contribuições podem ser deduzidas até 12% da renda bruta tributável, e o IR do resgate incide sobre o total. No VGBL não há dedução, e o IR incide só sobre os rendimentos.", "alternativeExplanations": {"A": "No PGBL, o IR incide sobre todo o valor resgatado, não há isenção.", "B": "Correto. O PGBL permite essa dedução; em troca, o IR no resgate incide sobre o valor total.", "C": "Essa é característica do VGBL, não do PGBL.", "D": "Planos de previdência não são cobertos pelo FGC.", "E": "A dedução é limitada a 12% da renda bruta tributável anual."}, "tags": ["previdencia", "pgbl", "vgbl", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["previdencia", "pgbl", "vgbl"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-06", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Crédito", "subtopic": "Cartão de crédito", "difficulty": "medio", "type": "multiple-choice", "statement": "Desde 2024, para as faturas de cartão de crédito, a lei estabelece que os juros e encargos financeiros do crédito rotativo e do parcelamento da fatura", "alternatives": [{"id": "A", "text": "são livres, sem qualquer limite legal"}, {"id": "B", "text": "não podem ultrapassar 2% ao mês"}, {"id": "C", "text": "não podem ultrapassar o valor original da dívida"}, {"id": "D", "text": "devem ser iguais à taxa Selic"}, {"id": "E", "text": "só podem ser cobrados após 12 meses de atraso"}], "correctAnswer": "C", "explanation": "A Lei 14.690/2023, regulamentada pelo CMN, determinou que os juros e encargos do rotativo e do parcelamento da fatura do cartão não podem ultrapassar 100% do valor original da dívida, regra válida desde janeiro de 2024.", "alternativeExplanations": {"A": "Há limite legal: os encargos não podem superar o valor original da dívida.", "B": "Não há teto mensal fixo de 2% para o rotativo; o limite é de 100% sobre o valor original.", "C": "Correto. A Lei 14.690/2023 limitou juros e encargos a 100% do valor original da dívida.", "D": "Não existe vinculação obrigatória do rotativo à Selic.", "E": "Os encargos podem ser cobrados desde o uso do rotativo; o que existe é o limite total."}, "tags": ["cartao-de-credito", "credito", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cartao-de-credito", "credito"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-m-07", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Prevenção à lavagem de dinheiro", "subtopic": "Coaf", "difficulty": "medio", "type": "multiple-choice", "statement": "O Conselho de Controle de Atividades Financeiras (Coaf), que recebe as comunicações de operações suspeitas feitas pelos bancos, está atualmente vinculado administrativamente ao", "alternatives": [{"id": "A", "text": "Ministério da Justiça e Segurança Pública"}, {"id": "B", "text": "Conselho Monetário Nacional"}, {"id": "C", "text": "Ministério Público Federal"}, {"id": "D", "text": "Banco Central do Brasil"}, {"id": "E", "text": "Tribunal de Contas da União"}], "correctAnswer": "D", "explanation": "O Coaf é a unidade de inteligência financeira do Brasil. Ele recebe e analisa comunicações dos setores obrigados, como os bancos, e produz relatórios de inteligência. Desde a Lei 13.974/2020, é vinculado administrativamente ao Banco Central, com autonomia técnica.", "alternativeExplanations": {"A": "O Coaf chegou a ser transferido para esse ministério em 2019, mas a vinculação atual é ao BCB.", "B": "O CMN é órgão normativo do SFN e não abriga o Coaf.", "C": "O MPF pode receber relatórios de inteligência, mas o Coaf não é vinculado a ele.", "D": "Correto. Desde a Lei 13.974/2020, o Coaf está vinculado administrativamente ao Banco Central.", "E": "O TCU fiscaliza contas públicas e não abriga o Coaf."}, "tags": ["coaf", "pld", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["coaf", "pld"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-a-01", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Política monetária", "subtopic": "Meta de inflação", "difficulty": "avancado", "type": "multiple-choice", "statement": "No regime de meta contínua de inflação, em vigor desde 2025, considera-se que a meta foi descumprida quando", "alternatives": [{"id": "A", "text": "a inflação do ano-calendário, apurada em dezembro, fica fora do intervalo de tolerância"}, {"id": "B", "text": "a inflação mensal supera 0,5% em qualquer mês do ano"}, {"id": "C", "text": "o Copom altera a Selic mais de duas vezes no mesmo semestre"}, {"id": "D", "text": "a inflação acumulada fica acima do centro da meta por três meses"}, {"id": "E", "text": "a inflação acumulada em 12 meses fica fora do intervalo de tolerância por seis meses consecutivos"}], "correctAnswer": "E", "explanation": "Com o Decreto 12.079/2024, o Brasil adotou a meta contínua a partir de 2025: a inflação acumulada em 12 meses é acompanhada mês a mês. Se ficar fora do intervalo de tolerância por seis meses consecutivos, a meta é considerada descumprida e o Banco Central deve explicar os motivos publicamente.", "alternativeExplanations": {"A": "Esse era o critério do regime anterior, por ano-calendário.", "B": "O critério não usa a inflação de um mês isolado.", "C": "Mudanças na Selic não definem o descumprimento da meta.", "D": "O centro da meta não é o critério; vale o intervalo de tolerância, por seis meses seguidos.", "E": "Correto. Pelo Decreto 12.079/2024, o descumprimento ocorre após seis meses seguidos fora do intervalo."}, "tags": ["meta-de-inflacao", "politica-monetaria", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["meta-de-inflacao", "politica-monetaria"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-a-02", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Autonomia do Banco Central", "difficulty": "avancado", "type": "multiple-choice", "statement": "A Lei Complementar 179/2021, que trata da autonomia do Banco Central, estabeleceu que", "alternatives": [{"id": "A", "text": "o presidente e os diretores do BCB têm mandatos de quatro anos, não coincidentes com o mandato do Presidente da República"}, {"id": "B", "text": "o Banco Central passou a ser subordinado ao Ministério da Fazenda"}, {"id": "C", "text": "o presidente do BCB pode ser exonerado livremente a qualquer tempo pelo Presidente da República"}, {"id": "D", "text": "o Copom foi extinto e substituído pelo CMN"}, {"id": "E", "text": "o Banco Central passou a definir sozinho a meta de inflação"}], "correctAnswer": "A", "explanation": "A LC 179/2021 deu autonomia ao Banco Central. Presidente e diretores têm mandatos de quatro anos, não coincidentes com o do Presidente da República, e o BCB deixou de ter vinculação a ministério. O objetivo fundamental é a estabilidade de preços, com objetivos acessórios como suavizar flutuações da atividade e fomentar o pleno emprego.", "alternativeExplanations": {"A": "Correto. Os mandatos fixos e não coincidentes são o núcleo da autonomia.", "B": "A lei fez o contrário: o BCB deixou de ter vinculação a ministério.", "C": "A exoneração passou a depender de hipóteses previstas na lei.", "D": "O Copom continua existindo e define a meta da Selic.", "E": "A meta de inflação continua a ser definida pelo CMN."}, "tags": ["banco-central", "autonomia", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["banco-central", "autonomia"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-a-03", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Prevenção à lavagem de dinheiro", "subtopic": "Comunicações ao Coaf", "difficulty": "avancado", "type": "multiple-choice", "statement": "De acordo com as regras de prevenção à lavagem de dinheiro do Banco Central, ao identificar uma operação suspeita, a instituição financeira deve comunicá-la ao Coaf e", "alternatives": [{"id": "A", "text": "pedir autorização prévia ao cliente para enviar a comunicação"}, {"id": "B", "text": "não dar ciência da comunicação ao cliente envolvido"}, {"id": "C", "text": "encerrar imediatamente a conta e devolver o saldo ao cliente"}, {"id": "D", "text": "informar o cliente por escrito no prazo de cinco dias úteis"}, {"id": "E", "text": "aguardar o fim do ano para enviar todas as comunicações juntas"}], "correctAnswer": "B", "explanation": "As normas de PLD/FT, como a Lei 9.613/1998 e a Circular BCB 3.978/2020, determinam que a instituição comunique ao Coaf as operações suspeitas e mantenha sigilo: o cliente não pode ser avisado. Avisar o envolvido prejudicaria a investigação.", "alternativeExplanations": {"A": "A comunicação não depende de autorização do cliente.", "B": "Correto. É vedado avisar o cliente sobre a comunicação, para não prejudicar a apuração.", "C": "A regra não exige o encerramento imediato; o foco é comunicar e manter o sigilo.", "D": "Avisar o cliente é justamente o que a regra proíbe.", "E": "As comunicações têm prazo curto; não são enviadas de forma anual."}, "tags": ["pld", "coaf", "comunicacao", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pld", "coaf", "comunicacao"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-a-04", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Produtos e serviços bancários", "subtopic": "Tributação de renda fixa", "difficulty": "avancado", "type": "multiple-choice", "statement": "Um CDB de pessoa física foi resgatado após 400 dias da aplicação. Pela tabela regressiva do Imposto de Renda, a alíquota aplicada sobre o rendimento é de", "alternatives": [{"id": "A", "text": "22,5%"}, {"id": "B", "text": "20%"}, {"id": "C", "text": "17,5%"}, {"id": "D", "text": "15%"}, {"id": "E", "text": "isento"}], "correctAnswer": "C", "explanation": "A tabela regressiva da renda fixa tributa o rendimento em 22,5% até 180 dias, 20% de 181 a 360 dias, 17,5% de 361 a 720 dias e 15% acima de 720 dias. Com 400 dias, a alíquota é de 17,5%.", "alternativeExplanations": {"A": "22,5% vale para aplicações de até 180 dias.", "B": "20% vale para prazos de 181 a 360 dias.", "C": "Correto. Para prazos de 361 a 720 dias, a alíquota é de 17,5%.", "D": "15% vale apenas para prazos acima de 720 dias.", "E": "O CDB não é isento de IR para pessoa física."}, "tags": ["cdb", "imposto-de-renda", "renda-fixa", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdb", "imposto-de-renda", "renda-fixa"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-a-05", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Pix", "subtopic": "Mecanismo Especial de Devolução", "difficulty": "avancado", "type": "multiple-choice", "statement": "Um cliente foi vítima de golpe e fez um Pix para um fraudador. O Mecanismo Especial de Devolução (MED) do Pix permite que", "alternatives": [{"id": "A", "text": "o próprio pagador cancele o Pix pelo aplicativo, sem análise, em até 24 horas"}, {"id": "B", "text": "o Banco Central reembolse o cliente com recursos próprios"}, {"id": "C", "text": "o FGC cubra o prejuízo, até R$ 250 mil"}, {"id": "D", "text": "a instituição do recebedor bloqueie os recursos e, confirmada a fraude, devolva os valores ao pagador"}, {"id": "E", "text": "a transação seja estornada automaticamente sempre que o pagador desistir da compra"}], "correctAnswer": "D", "explanation": "O MED permite devolver valores de um Pix em casos de fraude ou falha operacional. Após a contestação, a instituição do recebedor pode bloquear os recursos; confirmada a fraude, devolve o que estiver disponível. A versão 2.0, obrigatória desde 2026, também rastreia contas que receberam o dinheiro em seguida.", "alternativeExplanations": {"A": "Não existe cancelamento livre pelo pagador; o MED depende de contestação e análise.", "B": "O BCB não reembolsa vítimas; a devolução usa os recursos bloqueados na conta de destino.", "C": "O FGC protege depósitos em caso de quebra de instituição, não golpes.", "D": "Correto. O MED prevê bloqueio cautelar, análise e devolução quando a fraude é confirmada.", "E": "Desistência comercial não é hipótese do MED, que trata de fraude e falha operacional."}, "tags": ["pix", "med", "fraude", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pix", "med", "fraude"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-mc-a-06", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Mercado de capitais", "subtopic": "Ações", "difficulty": "avancado", "type": "multiple-choice", "statement": "Sobre as ações emitidas pelas sociedades anônimas, é correto afirmar que", "alternatives": [{"id": "A", "text": "as ações ordinárias não dão direito a voto nas assembleias"}, {"id": "B", "text": "toda ação negociada na bolsa é garantida pelo FGC"}, {"id": "C", "text": "o lucro com a venda de ações é sempre isento de Imposto de Renda"}, {"id": "D", "text": "debêntures e ações dão ao investidor a mesma condição de sócio da empresa"}, {"id": "E", "text": "as ações preferenciais podem ter restrição ao direito de voto em troca de vantagens, como prioridade na distribuição de dividendos"}], "correctAnswer": "E", "explanation": "As ações ordinárias (ON) dão direito a voto. As preferenciais (PN) podem ter o voto restrito, mas oferecem vantagens como prioridade nos dividendos ou no reembolso de capital. Quem compra ações é sócio da empresa; quem compra debêntures é credor.", "alternativeExplanations": {"A": "São as ações ordinárias (ON) que conferem direito a voto.", "B": "Ações não têm cobertura do FGC.", "C": "Há isenção apenas em hipóteses específicas; em regra, o ganho é tributado.", "D": "O debenturista é credor da empresa; quem tem ações é sócio.", "E": "Correto. As PN costumam ter voto restrito e, em troca, vantagens patrimoniais."}, "tags": ["acoes", "mercado-de-capitais", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["acoes", "mercado-de-capitais"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-01", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Banco Central", "difficulty": "iniciante", "type": "true-false", "statement": "Cabe ao Banco Central do Brasil, em nome da União, a emissão de papel-moeda e de moeda metálica.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A Constituição atribui à União a competência de emitir moeda, exercida exclusivamente pelo Banco Central (art. 164). A Casa da Moeda fabrica as cédulas e moedas, mas quem as emite é o BCB.", "alternativeExplanations": {"V": "Correto. A emissão de moeda é competência exclusiva do Banco Central, ainda que a fabricação seja da Casa da Moeda.", "F": "Incorreto. A emissão de moeda é competência exclusiva do Banco Central, ainda que a fabricação seja da Casa da Moeda."}, "tags": ["banco-central", "moeda", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["banco-central", "moeda"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-02", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Pix", "subtopic": "Funcionamento", "difficulty": "iniciante", "type": "true-false", "statement": "O Pix funciona apenas em dias úteis e em horário bancário, das 10h às 16h.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O Pix funciona 24 horas por dia, 7 dias por semana, inclusive em fins de semana e feriados, com liquidação em poucos segundos.", "alternativeExplanations": {"V": "Incorreto. O Pix opera em tempo integral, todos os dias do ano.", "F": "Correto. O Pix opera em tempo integral, todos os dias do ano."}, "tags": ["pix", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pix"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-03", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Fundo Garantidor de Créditos", "subtopic": "Cobertura", "difficulty": "iniciante", "type": "true-false", "statement": "Os valores mantidos em conta corrente e em caderneta de poupança estão entre os depósitos cobertos pelo FGC.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Depósitos à vista (conta corrente) e depósitos de poupança estão entre os créditos garantidos pelo FGC, dentro do limite de R$ 250 mil por CPF por instituição.", "alternativeExplanations": {"V": "Correto. Conta corrente e poupança fazem parte da cobertura do FGC.", "F": "Incorreto. Conta corrente e poupança fazem parte da cobertura do FGC."}, "tags": ["fgc", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["fgc"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-04", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Mercado de capitais", "subtopic": "CVM", "difficulty": "iniciante", "type": "true-false", "statement": "A Comissão de Valores Mobiliários (CVM) é a entidade responsável por regular e fiscalizar o mercado de ações, debêntures e fundos de investimento.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A CVM, criada pela Lei 6.385/1976, regula e fiscaliza o mercado de valores mobiliários, o que inclui ações, debêntures e fundos de investimento.", "alternativeExplanations": {"V": "Correto. Regular o mercado de valores mobiliários é justamente a função da CVM.", "F": "Incorreto. Regular o mercado de valores mobiliários é justamente a função da CVM."}, "tags": ["cvm", "mercado-de-capitais", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cvm", "mercado-de-capitais"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-05", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Garantias", "subtopic": "Hipoteca", "difficulty": "iniciante", "type": "true-false", "statement": "A hipoteca é a garantia real típica para bens móveis, como joias e máquinas, que são entregues à guarda do credor.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A garantia real sobre bens móveis com entrega ao credor é o penhor. A hipoteca recai, em regra, sobre bens imóveis (além de navios e aeronaves), e o devedor continua na posse do bem.", "alternativeExplanations": {"V": "Incorreto. A descrição corresponde ao penhor; a hipoteca recai sobre imóveis.", "F": "Correto. A descrição corresponde ao penhor; a hipoteca recai sobre imóveis."}, "tags": ["garantias", "hipoteca", "penhor", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["garantias", "hipoteca", "penhor"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-06", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Produtos e serviços bancários", "subtopic": "Cheque", "difficulty": "iniciante", "type": "true-false", "statement": "O cheque é uma ordem de pagamento à vista: mesmo que tenha data futura (pré-datado), o banco pode pagá-lo se for apresentado antes dessa data.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "Pela Lei do Cheque (Lei 7.357/1985), o cheque é pagável à vista, e qualquer menção em contrário é considerada não escrita. O pré-datado é um acordo entre as partes; a apresentação antecipada pode gerar responsabilidade de quem a fez, mas o banco pode pagar.", "alternativeExplanations": {"V": "Correto. O cheque é sempre pagável à vista perante o banco, mesmo com data futura.", "F": "Incorreto. O cheque é sempre pagável à vista perante o banco, mesmo com data futura."}, "tags": ["cheque", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cheque"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-i-07", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Prevenção à lavagem de dinheiro", "subtopic": "Conceito", "difficulty": "iniciante", "type": "true-false", "statement": "Lavagem de dinheiro é a prática de dar aparência lícita a recursos obtidos de forma ilícita.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "A Lei 9.613/1998 define como crime ocultar ou dissimular a natureza, origem, localização, disposição, movimentação ou propriedade de bens provenientes de infração penal, ou seja, dar aparência legal a dinheiro sujo.", "alternativeExplanations": {"V": "Correto. Dar aparência legal a recursos de origem ilícita é exatamente o que caracteriza a lavagem.", "F": "Incorreto. Dar aparência legal a recursos de origem ilícita é exatamente o que caracteriza a lavagem."}, "tags": ["pld", "lavagem-de-dinheiro", "concursos", "bancarios", "iniciante"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pld", "lavagem-de-dinheiro"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-01", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Conselho Monetário Nacional", "difficulty": "medio", "type": "true-false", "statement": "O Conselho Monetário Nacional é composto pelo Ministro da Fazenda, que o preside, pelo Ministro do Planejamento e Orçamento e pelo Presidente do Banco Central.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O CMN tem três integrantes: o Ministro da Fazenda (presidente do conselho), o Ministro do Planejamento e Orçamento e o Presidente do Banco Central.", "alternativeExplanations": {"V": "Correto. Essa é exatamente a composição atual do CMN.", "F": "Incorreto. Essa é exatamente a composição atual do CMN."}, "tags": ["cmn", "sfn", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cmn", "sfn"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-02", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Política monetária", "subtopic": "Open market", "difficulty": "medio", "type": "true-false", "statement": "Quando o Banco Central vende títulos públicos no mercado aberto, ele injeta dinheiro na economia e aumenta a liquidez.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Ao vender títulos, o Banco Central recebe dinheiro dos bancos e retira moeda de circulação, reduzindo a liquidez. Para injetar dinheiro, ele compra títulos.", "alternativeExplanations": {"V": "Incorreto. Vender títulos retira moeda da economia; quem injeta liquidez é a compra de títulos.", "F": "Correto. Vender títulos retira moeda da economia; quem injeta liquidez é a compra de títulos."}, "tags": ["open-market", "politica-monetaria", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["open-market", "politica-monetaria"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-03", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Garantias", "subtopic": "Fiança", "difficulty": "medio", "type": "true-false", "statement": "Na fiança, o fiador pode exigir que primeiro sejam executados os bens do devedor principal (benefício de ordem), salvo se tiver renunciado a esse direito no contrato.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O Código Civil garante ao fiador o benefício de ordem: ele pode exigir que os bens do devedor sejam executados antes dos seus. Esse benefício não vale se o fiador renunciou a ele, se obrigou como principal pagador ou devedor solidário, ou se o devedor for insolvente ou falido.", "alternativeExplanations": {"V": "Correto. O benefício de ordem é a regra na fiança, admitindo renúncia contratual.", "F": "Incorreto. O benefício de ordem é a regra na fiança, admitindo renúncia contratual."}, "tags": ["garantias", "fianca", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["garantias", "fianca"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-04", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Crédito", "subtopic": "Custo Efetivo Total", "difficulty": "medio", "type": "true-false", "statement": "Nas operações de crédito com pessoas físicas, a instituição só é obrigada a informar a taxa de juros, sem precisar informar o Custo Efetivo Total (CET).", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A regulamentação do CMN obriga as instituições a informar previamente o CET, que reúne juros, tarifas, tributos, seguros e demais encargos da operação, expresso em taxa percentual anual.", "alternativeExplanations": {"V": "Incorreto. Informar o CET antes da contratação é obrigatório nas operações de crédito.", "F": "Correto. Informar o CET antes da contratação é obrigatório nas operações de crédito."}, "tags": ["credito", "cet", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["credito", "cet"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-05", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Open Finance", "subtopic": "Consentimento", "difficulty": "medio", "type": "true-false", "statement": "No Open Finance, o compartilhamento de dados do cliente entre instituições depende do consentimento do próprio cliente.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O Open Finance é o compartilhamento padronizado de dados e serviços entre instituições autorizadas, sempre mediante consentimento do cliente, que pode revogá-lo a qualquer momento.", "alternativeExplanations": {"V": "Correto. O consentimento do cliente é a base do compartilhamento no Open Finance.", "F": "Incorreto. O consentimento do cliente é a base do compartilhamento no Open Finance."}, "tags": ["open-finance", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["open-finance"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-06", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Produtos e serviços bancários", "subtopic": "LCI e LCA", "difficulty": "medio", "type": "true-false", "statement": "As Letras de Crédito Imobiliário (LCI) e do Agronegócio (LCA) são títulos emitidos por instituições financeiras e contam com a garantia do FGC.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "LCI e LCA são títulos de renda fixa emitidos por instituições financeiras, lastreados em créditos imobiliários e do agronegócio, e estão entre os produtos cobertos pelo FGC.", "alternativeExplanations": {"V": "Correto. LCI e LCA são emitidas por bancos e estão na lista de cobertura do FGC.", "F": "Incorreto. LCI e LCA são emitidas por bancos e estão na lista de cobertura do FGC."}, "tags": ["lci", "lca", "fgc", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["lci", "lca", "fgc"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-m-07", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Ética e conduta", "subtopic": "Defesa do consumidor bancário", "difficulty": "medio", "type": "true-false", "statement": "O Código de Defesa do Consumidor não se aplica às relações entre os bancos e seus clientes, que são regidas apenas pelas normas do Banco Central.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A Súmula 297 do STJ afirma que o Código de Defesa do Consumidor é aplicável às instituições financeiras. As normas do Banco Central valem em conjunto com o CDC.", "alternativeExplanations": {"V": "Incorreto. O STJ pacificou que o CDC se aplica às instituições financeiras (Súmula 297).", "F": "Correto. O STJ pacificou que o CDC se aplica às instituições financeiras (Súmula 297)."}, "tags": ["cdc", "consumidor", "concursos", "bancarios", "medio"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cdc", "consumidor"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-a-01", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Produtos e serviços bancários", "subtopic": "Caderneta de poupança", "difficulty": "avancado", "type": "true-false", "statement": "Quando a meta da taxa Selic está em 10% ao ano, a remuneração dos depósitos de poupança corresponde a 70% da Selic mais a Taxa Referencial (TR).", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "A regra dos 70% da Selic + TR vale apenas quando a meta da Selic está em até 8,5% ao ano. Com a Selic em 10% ao ano, a poupança rende 0,5% ao mês + TR.", "alternativeExplanations": {"V": "Incorreto. Com a Selic acima de 8,5% ao ano, vale a regra de 0,5% ao mês + TR.", "F": "Correto. Com a Selic acima de 8,5% ao ano, vale a regra de 0,5% ao mês + TR."}, "tags": ["poupanca", "selic", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["poupanca", "selic"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-a-02", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Fundo Garantidor de Créditos", "subtopic": "Teto global", "difficulty": "avancado", "type": "true-false", "statement": "Além do limite por instituição, o FGC aplica um teto global de R$ 1 milhão por CPF, renovado a cada período de quatro anos, para as garantias pagas a um mesmo investidor.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "O estatuto do FGC prevê, além do limite de R$ 250 mil por instituição, um teto de R$ 1 milhão para garantias pagas a um mesmo CPF ou CNPJ em cada período de quatro anos.", "alternativeExplanations": {"V": "Correto. O teto global de R$ 1 milhão a cada quatro anos está previsto no estatuto do FGC.", "F": "Incorreto. O teto global de R$ 1 milhão a cada quatro anos está previsto no estatuto do FGC."}, "tags": ["fgc", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["fgc"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-a-03", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Prevenção à lavagem de dinheiro", "subtopic": "Pessoas expostas politicamente", "difficulty": "avancado", "type": "true-false", "statement": "As instituições financeiras devem dispensar procedimentos especiais de monitoramento para clientes classificados como pessoas expostas politicamente (PEP), por se tratar de agentes públicos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Ocorre o oposto: as normas de PLD/FT exigem atenção especial e monitoramento reforçado das operações de pessoas expostas politicamente, por representarem maior risco de lavagem de dinheiro e corrupção.", "alternativeExplanations": {"V": "Incorreto. PEP exigem diligência reforçada, e não a dispensa de controles.", "F": "Correto. PEP exigem diligência reforçada, e não a dispensa de controles."}, "tags": ["pld", "pep", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["pld", "pep"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-a-04", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Previdência complementar", "difficulty": "avancado", "type": "true-false", "statement": "As entidades fechadas de previdência complementar (fundos de pensão) são supervisionadas pela Previc, enquanto as entidades abertas são supervisionadas pela Susep.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "V", "explanation": "No SFN, a previdência complementar fechada (fundos de pensão ligados a empresas ou associações) é supervisionada pela Previc, e a previdência aberta, oferecida ao público por seguradoras e entidades abertas, pela Susep.", "alternativeExplanations": {"V": "Correto. Essa é a divisão correta entre Previc (fechada) e Susep (aberta).", "F": "Incorreto. Essa é a divisão correta entre Previc (fechada) e Susep (aberta)."}, "tags": ["previc", "susep", "previdencia", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["previc", "susep", "previdencia"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-a-05", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Crédito", "subtopic": "Cadastro positivo", "difficulty": "avancado", "type": "true-false", "statement": "Pela legislação atual do Cadastro Positivo, o consumidor precisa autorizar expressamente a abertura do seu cadastro antes que seus dados de pagamento sejam incluídos.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "Desde a Lei Complementar 166/2019, a inclusão no Cadastro Positivo é automática. O consumidor é comunicado e pode pedir o cancelamento a qualquer momento (modelo de opt-out).", "alternativeExplanations": {"V": "Incorreto. A inclusão passou a ser automática em 2019; o consumidor pode pedir a saída depois.", "F": "Correto. A inclusão passou a ser automática em 2019; o consumidor pode pedir a saída depois."}, "tags": ["cadastro-positivo", "credito", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["cadastro-positivo", "credito"], "origin": "nabulab"},
  {"id": "conhecimentos-bancarios-conc-v1-vf-a-06", "area": "Concursos Bancários", "subject": "conhecimentos-bancarios", "subjectName": "Conhecimentos Bancários", "topic": "Sistema Financeiro Nacional", "subtopic": "Inovação no sistema financeiro", "difficulty": "avancado", "type": "true-false", "statement": "O Drex foi lançado ao público em 2025 como moeda digital oficial, e os brasileiros já podem guardá-lo e usá-lo em pagamentos no dia a dia.", "alternatives": [{"id": "V", "text": "Verdadeiro"}, {"id": "F", "text": "Falso"}], "correctAnswer": "F", "explanation": "O Drex não chegou ao público como moeda digital. Em novembro de 2025, o Banco Central abandonou a infraestrutura de blockchain testada nas fases piloto e reorientou o projeto para soluções de infraestrutura financeira, como a tokenização de garantias.", "alternativeExplanations": {"V": "Incorreto. O Drex não foi lançado como moeda para uso do público; o projeto foi reorientado em 2025.", "F": "Correto. O Drex não foi lançado como moeda para uso do público; o projeto foi reorientado em 2025."}, "tags": ["drex", "inovacao", "concursos", "bancarios", "avancado"], "examTags": ["bancarios"], "educationLevel": "ensino-medio", "skills": ["drex", "inovacao"], "origin": "nabulab"},
];
